PRAGMA foreign_keys=ON;
CREATE TABLE dim_unidade (unidade_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,cidade TEXT NOT NULL,uf TEXT NOT NULL,regiao TEXT NOT NULL,capacidade_dia INTEGER NOT NULL);
CREATE TABLE dim_plano (plano_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,valor_mensal REAL NOT NULL,visitas_inclusas INTEGER NOT NULL,desconto_loja_pct REAL NOT NULL,beneficios TEXT NOT NULL);
CREATE TABLE dim_produto (produto_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,categoria TEXT NOT NULL,preco REAL NOT NULL,custo REAL NOT NULL);
CREATE TABLE dim_cliente (cliente_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,data_nascimento TEXT NOT NULL,genero TEXT NOT NULL,cidade TEXT NOT NULL,uf TEXT NOT NULL,data_cadastro TEXT NOT NULL,origem_cadastro TEXT NOT NULL);
CREATE TABLE fato_membro (membro_id INTEGER PRIMARY KEY,cliente_id INTEGER NOT NULL,plano_id INTEGER NOT NULL,data_inicio TEXT NOT NULL,data_fim TEXT,status TEXT NOT NULL,forma_pagamento TEXT NOT NULL,campanha_id INTEGER,FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id),FOREIGN KEY(plano_id) REFERENCES dim_plano(plano_id));
CREATE TABLE dim_evento (evento_id INTEGER PRIMARY KEY,unidade_id INTEGER NOT NULL,nome TEXT NOT NULL,tipo TEXT NOT NULL,data_evento TEXT NOT NULL,capacidade INTEGER NOT NULL,preco_unitario REAL NOT NULL,FOREIGN KEY(unidade_id) REFERENCES dim_unidade(unidade_id));
CREATE TABLE fato_visita (visita_id INTEGER PRIMARY KEY,cliente_id INTEGER NOT NULL,unidade_id INTEGER NOT NULL,data_visita TEXT NOT NULL,canal TEXT NOT NULL,qtd_pessoas INTEGER NOT NULL,valor_pago REAL NOT NULL,tempo_permanencia_horas REAL NOT NULL,FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id),FOREIGN KEY(unidade_id) REFERENCES dim_unidade(unidade_id));
CREATE TABLE fato_ingresso_evento (ingresso_id INTEGER PRIMARY KEY,evento_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_compra TEXT NOT NULL,quantidade INTEGER NOT NULL,valor_total REAL NOT NULL,canal TEXT NOT NULL,FOREIGN KEY(evento_id) REFERENCES dim_evento(evento_id),FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id));
CREATE TABLE fato_venda (venda_id INTEGER PRIMARY KEY,cliente_id INTEGER NOT NULL,unidade_id INTEGER NOT NULL,data_venda TEXT NOT NULL,canal TEXT NOT NULL,valor_bruto REAL NOT NULL,desconto_pct REAL NOT NULL,valor_liquido REAL NOT NULL,forma_pagamento TEXT NOT NULL,FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id),FOREIGN KEY(unidade_id) REFERENCES dim_unidade(unidade_id));
CREATE TABLE fato_item_venda (item_id INTEGER PRIMARY KEY,venda_id INTEGER NOT NULL,produto_id INTEGER NOT NULL,quantidade INTEGER NOT NULL,preco_unitario REAL NOT NULL,valor_liquido REAL NOT NULL,FOREIGN KEY(venda_id) REFERENCES fato_venda(venda_id),FOREIGN KEY(produto_id) REFERENCES dim_produto(produto_id));
CREATE TABLE dim_campanha (campanha_id INTEGER PRIMARY KEY,nome TEXT NOT NULL,canal TEXT NOT NULL,objetivo TEXT NOT NULL,data_inicio TEXT NOT NULL,data_fim TEXT NOT NULL,investimento REAL NOT NULL);
CREATE TABLE fato_interacao_campanha (interacao_id INTEGER PRIMARY KEY,campanha_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_interacao TEXT NOT NULL,impressoes INTEGER NOT NULL,clique INTEGER NOT NULL,conversao INTEGER NOT NULL,receita_atribuida REAL NOT NULL,FOREIGN KEY(campanha_id) REFERENCES dim_campanha(campanha_id),FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id));
CREATE TABLE fato_avaliacao (avaliacao_id INTEGER PRIMARY KEY,visita_id INTEGER NOT NULL,cliente_id INTEGER NOT NULL,data_avaliacao TEXT NOT NULL,nps INTEGER NOT NULL CHECK(nps BETWEEN 0 AND 10),nota INTEGER NOT NULL CHECK(nota BETWEEN 1 AND 5),tema TEXT NOT NULL,tipo_feedback TEXT NOT NULL,FOREIGN KEY(visita_id) REFERENCES fato_visita(visita_id),FOREIGN KEY(cliente_id) REFERENCES dim_cliente(cliente_id));
CREATE INDEX idx_visita_data ON fato_visita(data_visita);
CREATE INDEX idx_venda_data ON fato_venda(data_venda);
CREATE INDEX idx_membro_status ON fato_membro(status);
CREATE INDEX idx_interacao_campanha ON fato_interacao_campanha(campanha_id);
